\set ON_ERROR_STOP on
begin;
create function pg_temp.staff_command(p_id uuid,p_revision bigint,p_command_id uuid,p_operation text,p_input jsonb) returns jsonb language plpgsql as $$declare uid uuid;begin uid:='81000000-0000-4000-8000-000000000001';return public.command_patient_test_request(uid,auth.uid(),true,p_id,p_revision,p_command_id,p_operation,p_input);end$$;
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'TEST %',label;end if;end$$;
create function pg_temp.must_fail(command text,expected text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlerrm like '%'||expected||'%' then return;end if;raise;end;raise exception 'TEST unexpectedly passed: %',command;end$$;
insert into auth.users(id,phone,phone_confirmed_at) values
('81000000-0000-4000-8000-000000000001','37499000801',now()),('81000000-0000-4000-8000-000000000002','37499000802',now()),
('81000000-0000-4000-8000-000000000003',null,null),('81000000-0000-4000-8000-000000000004',null,null),('81000000-0000-4000-8000-000000000005',null,null);
update public.profiles set display_name='Synthetic booking fixture',birth_date='1980-01-01',biological_sex='female' where id::text like '81000000%';
insert into public.patient_consents(user_id,version) select id,'patient-pilot-v1' from auth.users where id::text like '81000000%';
insert into public.patient_assessments(user_id,revision,completed_at) select id,2,now() from auth.users where id::text like '81000000%';
insert into public.workspace_clinics(id,name) values('81000000-0000-4000-8000-000000000010','SYNTHETIC booking clinic');
insert into public.workspace_staff(user_id,role,display_name,clinic_id) values
('81000000-0000-4000-8000-000000000003','admin','Synthetic admin',null),('81000000-0000-4000-8000-000000000004','doctor','Synthetic doctor','81000000-0000-4000-8000-000000000010'),('81000000-0000-4000-8000-000000000005','nurse','Synthetic nurse','81000000-0000-4000-8000-000000000010');
create temp table ctx as select '81000000-0000-4000-8000-000000000001'::uuid uid,'81000000-0000-4000-8000-000000000020'::uuid rid,public.patient_test_context('81000000-0000-4000-8000-000000000001')->>'token' token,
jsonb_build_object('startsAt',now()+interval '10 days','timezone','Asia/Yerevan','mode','office','location','Synthetic preferred office') terms,
'[{"id":"lipid-panel","title":"Lipid panel","method":"lab"}]'::jsonb requirements;
grant select on ctx to authenticated,service_role;
-- Privileged initial fixture only; public creator is now existing-ID replay-only.
select public._legacy_create_patient_test_request(uid,rid,token,terms,requirements,'test-engine') from ctx;
set local role service_role;
select public.create_patient_test_request(uid,rid,token,terms,requirements,'test-engine') from ctx;
select pg_temp.must_fail(format('select public.create_patient_test_request(%L,%L,%L,%L,%L,''test-engine'')',uid,rid,token,terms||'{"location":"Different place"}',requirements),'different details') from ctx;
reset role;
select pg_temp.check_true((select count(*)=1 from public.patient_test_requests where user_id=(select uid from ctx)),'same create replays one row');
select pg_temp.check_true((select not (requested_terms ? 'endsAt') from public.patient_test_requests where id=(select rid from ctx)),'start-only preference stored without invented duration');
select pg_temp.check_true((select requested_terms->>'mode'='office' from public.patient_test_requests where id=(select rid from ctx)),'office location preference persists');
select pg_temp.check_true((select count(*)=1 from public.patient_clinical_cases where user_id=(select uid from ctx)),'atomic enrollment');
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select pg_temp.check_true((select count(*)=0 from public.patient_test_requests where user_id=(select uid from ctx)),'cross-owner RLS');
select pg_temp.must_fail('select public.patient_test_booking_requests(''81000000-0000-4000-8000-000000000001'')','operations access');
select pg_temp.must_fail('delete from public.patient_test_requests','permission denied');
select pg_temp.must_fail(format('select public.create_patient_test_request(%L,%L,%L,%L,%L,''test-engine'')',uid,gen_random_uuid(),token,terms,requirements),'permission denied') from ctx;
reset role;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000005',true);
set local role service_role;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,0,gen_random_uuid(),''confirm'',''{}'')',rid),'assigned operations access') from ctx;
reset role;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000003',true);
create temp table proposal as select jsonb_build_object('provider','SYNTHETIC provider','terms',terms||jsonb_build_object('endsAt',now()+interval '10 days 1 hour'),'obtainedAt',now(),'channel','phone','source','Synthetic SQL test, no actual contact','preparation','Synthetic preparation only','replacesExisting',false,'engine',jsonb_build_object('version','test-engine','tests',requirements,'sourceToken',token)) input from ctx;
grant select on proposal to authenticated,service_role;
set local role authenticated;
select pg_temp.must_fail(format('select public.staff_patient_test_command(%L,0,gen_random_uuid(),''confirm'',%L)',rid,input),'permission denied') from ctx,proposal;
reset role;
set local role service_role;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,0,gen_random_uuid(),''confirm'',%L)',rid,jsonb_set(input,'{engine,version}','"next-engine"')),'algorithm changed') from ctx,proposal;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,0,gen_random_uuid(),''confirm'',%L)',rid,jsonb_set(input,'{engine,tests}','[]')),'requirements changed') from ctx,proposal;
reset role;
set local role service_role;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,0,gen_random_uuid(),''confirm'',%L)',rid,jsonb_set(input,'{terms}',terms)),'complete actual provider terms') from ctx,proposal;
select pg_temp.staff_command(rid,0,'81000000-0000-4000-8000-000000000030','confirm',input) from ctx,proposal;
select pg_temp.staff_command(rid,0,'81000000-0000-4000-8000-000000000030','confirm',input) from ctx,proposal;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,0,gen_random_uuid(),''confirm'',%L)',rid,input),'changed') from ctx,proposal;
reset role;
select pg_temp.check_true((select status='provider-proposed' and revision=1 and current_arrangement is null from public.patient_test_requests where user_id=(select uid from ctx)),'proposal requires acceptance and replay does not mutate');
savepoint declined_initial_proposal;
set local role service_role;
select public.command_patient_test_request(uid,uid,false,rid,1,gen_random_uuid(),'request-change',jsonb_build_object('terms',terms)) from ctx;
select pg_temp.staff_command(rid,2,gen_random_uuid(),'change-outcome',input||'{"outcome":"declined"}') from ctx,proposal;
reset role;
select pg_temp.check_true((select status='provider-proposed' and proposal is not null and current_arrangement is null from public.patient_test_requests where user_id=(select uid from ctx)),'declined change retains original external proposal');
rollback to declined_initial_proposal;
set local role service_role;
select pg_temp.must_fail(format('select public.command_patient_test_request(%L,%L,false,%L,1,gen_random_uuid(),''accept'',%L)',uid,uid,rid,jsonb_build_object('engine',jsonb_build_object('version','new-engine','tests',requirements,'sourceToken',token))),'algorithm changed') from ctx;
select public.command_patient_test_request(uid,uid,false,rid,1,gen_random_uuid(),'accept',jsonb_build_object('engine',jsonb_build_object('version','test-engine','tests',requirements,'sourceToken',token))) from ctx;
reset role;
savepoint replacement;
set local role service_role;
select pg_temp.staff_command(rid,2,gen_random_uuid(),'confirm',jsonb_set(input||'{"replacesExisting":true}','{terms,location}','"Synthetic replacement location"')) from ctx,proposal;
select public.command_patient_test_request(uid,uid,false,rid,3,gen_random_uuid(),'accept',jsonb_build_object('engine',jsonb_build_object('version','test-engine','tests',requirements,'sourceToken',token))) from ctx;
reset role;
select pg_temp.check_true((select status='change-pending' and pending_change->>'memberAccepted'='true' and current_arrangement#>>'{terms,location}'='Synthetic preferred office' and proposal#>>'{terms,location}'='Synthetic replacement location' from public.patient_test_requests where user_id=(select uid from ctx)),'member acceptance retains existing external arrangement');
select pg_temp.check_true((select current_arrangement#>>'{terms,mode}'='office' from public.patient_test_requests where id=(select rid from ctx)),'accepted provider office terms retained');
set local role service_role;
select pg_temp.staff_command(rid,4,gen_random_uuid(),'change-outcome',input||'{"outcome":"accepted"}') from ctx,proposal;
reset role;
select pg_temp.check_true((select status='confirmed' and proposal is null and current_arrangement#>>'{terms,location}'='Synthetic replacement location' from public.patient_test_requests where user_id=(select uid from ctx)),'actual provider replacement promotes accepted terms');
rollback to replacement;
set local role service_role;
select public.command_patient_test_request(uid,uid,false,rid,2,gen_random_uuid(),'cancel','{}') from ctx;
reset role;
select pg_temp.check_true((select status='change-pending' and current_arrangement is not null from public.patient_test_requests where user_id=(select uid from ctx)),'pending cancellation retains actual arrangement');
set local role service_role;
select pg_temp.staff_command(rid,3,gen_random_uuid(),'change-outcome',input||'{"outcome":"declined"}') from ctx,proposal;
reset role;
select pg_temp.check_true((select status='confirmed' and current_arrangement is not null from public.patient_test_requests where user_id=(select uid from ctx)),'declined cancellation restores confirmed arrangement');
update public.patient_assessments set revision=revision+1 where user_id=(select uid from ctx);
set local role service_role;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,0,''81000000-0000-4000-8000-000000000030'',''confirm'',%L)',rid,input),'requirements changed') from ctx,proposal;
reset role;
set local role service_role;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,4,gen_random_uuid(),''confirm'',%L)',rid,input||'{"replacesExisting":true}'),'requirements changed') from ctx,proposal;
reset role;
set local role service_role;
select public.command_patient_test_request(uid,uid,false,rid,4,gen_random_uuid(),'cancel','{}') from ctx;
reset role;
set local role service_role;
select pg_temp.staff_command(rid,5,gen_random_uuid(),'change-outcome',input||'{"outcome":"accepted"}') from ctx,proposal;
reset role;
select pg_temp.check_true((select status='cancelled' and current_arrangement is null from public.patient_test_requests where user_id=(select uid from ctx)),'actual accepted cancellation resolves arrangement even with stale assessment');
update public.workspace_staff set active=false where user_id='81000000-0000-4000-8000-000000000003';
set local role service_role;
select pg_temp.must_fail(format('select pg_temp.staff_command(%L,0,''81000000-0000-4000-8000-000000000030'',''confirm'',%L)',rid,input),'assigned operations access') from ctx,proposal;
reset role;
select pg_temp.check_true((select count(*)=0 from public.patient_care_plans where user_id=(select uid from ctx)),'operations did not publish clinical content');
rollback;
